  UPDATE lessons SET assessment_policy='{"version":"n5-assessment-v2","chapter":3,"title":"Bab 3 — Perkenalan diri","objectives":[{"id":"identity","canDo":"Mengenali nama, negara, serta profesi dan memilih ungkapan perkenalan yang sesuai."},{"id":"negation","canDo":"Memahami penyangkalan identitas dan memilih koreksi sopan yang sesuai situasi."},{"id":"question","canDo":"Memilih pertanyaan dan respons yang sesuai dengan informasi identitas yang diminta."},{"id":"addition","canDo":"Menentukan kesamaan identitas yang dinyatakan dengan も."},{"id":"relation","canDo":"Memahami hubungan orang dengan nama, keluarga, atau profesinya memakai の."},{"id":"stance","canDo":"Membedakan pertanyaan, permintaan konfirmasi, dan pemberian informasi baru."}],"boundary":{"grammar":["AはBです","AはBじゃありません／ではありません","AはBですか","も","の","ね／よ"],"notes":"Kana pada kalimat; target baca hanya kanji Bab3. Tidak memakai kata tunjuk Bab4, adjektiva, verba bebas, atau rantai の. Instruksi konteks berbahasa Indonesia."},"transferTask":{"prompt":"Latihan lisan opsional, di luar skor assessment: di pertemuan kelas pertama, gunakan kartu ini: Anda Rina, orang Indonesia, pelajar; Dodi juga pelajar; profesi Yuki belum diketahui. Perkenalkan diri, sampaikan persamaan dengan Dodi, lalu tanyakan profesi Yuki dengan beberapa kalimat pendek bahasa Jepang.","rubric":["Nama, kewarganegaraan, dan profesi yang disampaikan sesuai kartu.","Pola は…です, も, dan pertanyaan …ですか digunakan dengan tepat; formulasi sah yang setara diterima.","Pertanyaan meminta informasi yang belum diketahui; pernyataan も benar-benar menyatakan kesamaan."]},"passingScorePct":70,"categoryMinimumPct":50,"minimumObjectiveCorrect":1,"questionsPerForm":24}'::jsonb, questions_per_attempt=24 WHERE id=v_lesson;
